CREATE OR REPLACE TRIGGER VVRE_TRG_PROJ_ELEMENT_BF_INSERT
BEFORE INSERT ON VVRE_PROJ_ELEMENT
FOR EACH ROW
DECLARE
    v_total_elementos   NUMBER := 0;
    v_limite_projeto    NUMBER := 0;
BEGIN
    VVRE_GERAR_HIST_PROJ_COMP (3, 'Processo de validação de dados');
    -- Soma dos elementos já existentes para o projeto
    SELECT NVL(SUM(VL_ELEMENTO), 0)
    INTO v_total_elementos
    FROM VVRE_PROJ_ELEMENT
    WHERE NR_SEQ_PROJETO = :NEW.NR_SEQ_PROJETO;

    -- Buscar limite permitido do projeto
    SELECT (VL_PROJETO - VL_SALDO)
    INTO v_limite_projeto
    FROM VVRE_PROJ_COMPRAS
    WHERE NR_SEQUENCIA = :NEW.NR_SEQ_PROJETO;

    -- Validação
    IF (v_total_elementos + :NEW.VL_ELEMENTO) > v_limite_projeto THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'Valor do elemento ultrapassa o limite disponível do projeto.'
        );
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(
            -20002,
            'Projeto não encontrado na VVRE_PROJ_COMPRAS.'
        );
END;
/

